**完整答案（直接采用教材 5.6 的 MPNode）**

教材结点只有 **tag、exp、hp/coef、tp**。根结点的 exp=m；hp 指向最外层表头。每层表头的 tp 是本层指数项链；项结点的 exp 是当前变元指数，tag=ATOM 时 coef 是常数系数，tag=LIST 时 hp 指向下一变元层的表头。下面把最外层编号为 1，所以“第二变量”就是 target=2。

~~~~c
/* h 是某一变元层的表头；真正的项从 h->tp 开始。 */
static void ScaleHead(MPNode *h, float c);

static void ScaleCoefficient(MPNode *term, float c) {
    if (term->tag == ATOM) term->coef *= c;
    else                   ScaleHead(term->hp, c);
}

static void ScaleHead(MPNode *h, float c) {
    for (MPNode *p = h ? h->tp : NULL; p; p = p->tp)
        ScaleCoefficient(p, c);
}

/* 只释放 p 这一项及其 hp 子表，不沿 p->tp 释放兄弟。 */
static void FreeOneTerm(MPNode *p);

/* 返回 1 表示该层求导后已成为零多项式。 */
static int DiffHead(MPNode *h, int level, int target) {
    MPNode **link = &h->tp;
    while (*link) {
        MPNode *p = *link;

        if (level == target) {
            if (p->exp == 0) {             /* 常数项的导数为 0 */
                *link = p->tp;
                p->tp = NULL;
                FreeOneTerm(p);
                continue;
            }
            int e = p->exp;
            --p->exp;                       /* x^e -> x^(e-1) */
            ScaleCoefficient(p, (float)e); /* 系数整体乘 e */
        } else {                            /* target 尚在更内层 */
            int zero;
            if (p->tag == ATOM) zero = 1;  /* 不含第二变量 */
            else                zero = DiffHead(p->hp, level + 1, target);
            if (zero) {
                *link = p->tp;
                p->tp = NULL;
                FreeOneTerm(p);
                continue;
            }
        }
        link = &p->tp;
    }
    return h->tp == NULL;
}

void PartialBySecondVariable(MPList P) {
    if (!P || P->tag != LIST || P->exp < 2 || !P->hp) return;
    (void)DiffHead(P->hp, 1, 2);            /* 根和各层表头均保留 */
}
~~~~

FreeOneTerm 的实现规则是：若 tag=LIST，先递归释放 hp 所指的完整子表，再释放本项；若 tag=ATOM，直接释放本项。它绝不能顺着已断开的兄弟链之外继续释放。

正确性来自幂函数法则：目标层每项 $C x_2^e$ 被原地改成 $eC x_2^{e-1}$，$e=0$ 的项删除；外层只保留导数非零的系数子表。所有正指数同时减 1，原有指数次序不会改变。每个 MPNode 至多访问常数次，时间 $O(S)$，其中 $S$ 为结点总数；除递归栈 $O(m)$ 外附加空间为 $O(1)$。

