**完整答案（直接采用教材 5.6 的 MPNode）**

两个输入必须使用同一变元数组和同一层次顺序；每层表头后的 tp 链按 exp 递减。算法建立新结果，不修改输入。表头用 NewHeaderLike(h) 复制本层变元标记并令 tp=NULL；CloneOne(p) 只复制一个指数项，若 tag=LIST 则递归深拷贝 hp 子表，且返回项的 tp=NULL。

~~~~c
static MPNode *AddHead(const MPNode *a, const MPNode *b, int level, int m);

/* 在 h 表示的剩余变量多项式中加常数 c。 */
static void AddScalar(MPNode *h, float c, int level, int m) {
    if (c == 0) return;
    MPNode **link = &h->tp;
    while (*link && (*link)->exp > 0) link = &(*link)->tp;

    if (!*link || (*link)->exp < 0) {       /* 本层没有零次项 */
        MPNode *z = NewAtom(0, c);
        z->tp = *link; *link = z;
    } else if ((*link)->tag == ATOM) {
        (*link)->coef += c;
        if ((*link)->coef == 0) {
            MPNode *z = *link; *link = z->tp; free(z);
        }
    } else {                                /* 零次项仍是下一层多项式 */
        AddScalar((*link)->hp, c, level + 1, m);
        if ((*link)->hp->tp == NULL) {
            MPNode *z = *link; *link = z->tp;
            z->tp = NULL; FreeOneTerm(z);
        }
    }
}

/* p、q 的 exp 相同；返回该指数的和项，和为零则返回 NULL。 */
static MPNode *AddSame(const MPNode *p, const MPNode *q,
                       int level, int m) {
    if (p->tag == ATOM && q->tag == ATOM) {
        float c = p->coef + q->coef;
        return c == 0 ? NULL : NewAtom(p->exp, c);
    }

    MPNode *child;
    if (p->tag == LIST && q->tag == LIST) {
        child = AddHead(p->hp, q->hp, level + 1, m);
    } else if (p->tag == LIST) {
        child = CloneHead(p->hp);
        AddScalar(child, q->coef, level + 1, m);
    } else {
        child = CloneHead(q->hp);
        AddScalar(child, p->coef, level + 1, m);
    }
    if (child->tp == NULL) { FreeHead(child); return NULL; }
    return NewListTerm(p->exp, child);       /* tag=LIST, hp=child */
}

static MPNode *AddHead(const MPNode *a, const MPNode *b,
                       int level, int m) {
    MPNode *r = NewHeaderLike(a), **tail = &r->tp;
    const MPNode *p = a->tp, *q = b->tp;

    while (p && q) {
        MPNode *z;
        if (p->exp > q->exp)      { z = CloneOne(p); p = p->tp; }
        else if (p->exp < q->exp) { z = CloneOne(q); q = q->tp; }
        else { z = AddSame(p, q, level, m); p = p->tp; q = q->tp; }
        if (z) { *tail = z; tail = &z->tp; }
    }
    while (p) { MPNode *z=CloneOne(p); *tail=z; tail=&z->tp; p=p->tp; }
    while (q) { MPNode *z=CloneOne(q); *tail=z; tail=&z->tp; q=q->tp; }
    *tail = NULL;
    return r;
}

MPList AddMPoly(const MPList P, const MPList Q) {
    if (!P) return CloneRoot(Q);
    if (!Q) return CloneRoot(P);
    if (P->exp != Q->exp || !SameVariableOrder(P, Q)) return NULL;
    MPNode *R = NewRoot(P->exp);
    R->hp = AddHead(P->hp, Q->hp, 1, P->exp);
    R->tp = NULL;
    return R;
}
~~~~

同层归并时，较大指数项不可能再与另一链后续项同指数，可以直接复制；同指数项递归相加，系数和为零就不接入结果。

混合的 LIST+ATOM 不能直接相加两个字段：原子表示“不含其余变量的常数”，必须用 AddScalar 加到子多项式的全零指数项。这样结果仍只使用教材的 tag、exp、hp/coef、tp，保留各层表头且无零项。固定 $m$ 时，时间为 $O(S_P+S_Q)$、结果空间为 $O(S_R)$；一般写成 $O(S_P+S_Q+zm)$，其中 $z$ 是发生“子多项式加常数”的同指数项数，递归栈为 $O(m)$。

